function fmtDate(t){const d=new Date(t);const wd=d.toLocaleDateString("pt-BR",{weekday:"short"}).replace(".","");return wd.charAt(0).toUpperCase()+wd.slice(1)+", "+d.toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"})+" · "+String(d.getHours()).padStart(2,"0")+"h"+(d.getMinutes()?String(d.getMinutes()).padStart(2,"0"):"");}
function untilText(ms){if(ms<=0)return"agora";const d=Math.floor(ms/D),h=Math.floor((ms%D)/H);return d>0?`${d} dia${d>1?"s":""} e ${h}h`:h>0?`${h}h`:`${Math.ceil(ms/60e3)} min`;}
function ago(t){const m=Math.round((Date.now()-t)/60e3);return m<60?`há ${m} min`:m<1440?`há ${Math.round(m/60)}h`:`há ${Math.round(m/1440)} dia(s)`;}
function age(b){if(!b)return 0;const d=new Date(b+"T12:00:00"),n=new Date();let a=n.getFullYear()-d.getFullYear();if(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate()))a--;return a;}
