function errMsg(e){const m=((e&&e.message)||"")+"";
  if(/profiles_cpf_unique|duplicate key.*cpf/i.test(m))return "Este CPF já tem cadastro.";
  if(/Database error saving new user/i.test(m))return "Não foi possível criar o cadastro. Confira se o CPF ou o e-mail já não foram usados.";
  if(/already registered|already been registered/i.test(m))return "Este e-mail já tem conta. Toque em Entrar.";
  if(/Invalid login credentials/i.test(m))return "E-mail ou senha incorretos.";
  if(/Email not confirmed/i.test(m))return "Confirme o e-mail pelo link que enviamos antes de entrar.";
  if(/Password should be/i.test(m))return "A senha precisa ter pelo menos 6 caracteres.";
  if(/rate limit/i.test(m))return "Muitas tentativas. Espere um pouco e tente de novo.";
  if(/Failed to fetch|NetworkError|Load failed/i.test(m))return "Sem conexão. Confira a internet e tente de novo.";
  return m||"Algo deu errado. Tente de novo.";}
