async function signedMap(paths){paths=[...new Set(paths.filter(Boolean))];if(!paths.length)return{};try{const r=await SB.storage.from("photos").createSignedUrls(paths,3600),m={};((r&&r.data)||[]).forEach(x=>{if(x.signedUrl)m[x.path]=x.signedUrl;});return m;}catch(e){console.error(e);return{};}}
async function load(){
  const uid=SESSION.user.id;
  await SB.rpc("expire_overdue");
  const [pr,ev,cn,pa,ps]=await Promise.all([
    SB.from("profiles").select("*").eq("id",uid).single(),
    SB.from("events").select("*").order("starts_at"),
    SB.rpc("event_confirmed_counts"),
    SB.from("participations").select("*").eq("user_id",uid),
    SB.from("passes").select("event_id").eq("user_id",uid)]);
  if(pr.error)throw pr.error;
  S.profile=Object.assign(mapProfile(pr.data),{me:true});
  const cm={};(cn.data||[]).forEach(c=>cm[c.event_id]=Number(c.confirmed));
  S.events=(ev.data||[]).map(r=>mapEvent(r,cm[r.id]));
  S.mine={};S.matchAt={};S.mySent={};S.partId={};
  (pa.data||[]).forEach(p=>{S.mine[p.event_id]=p.status;S.matchAt[p.event_id]=new Date(p.matched_at).getTime();if(p.paid_sent_at)S.mySent[p.event_id]=new Date(p.paid_sent_at).getTime();S.partId[p.event_id]=p.id;});
  S.passed=(ps.data||[]).map(x=>x.event_id);
  const p=S.profile,m=await signedMap([p.selfie_path,...p.extra_paths]);
  S.my={selfie:m[p.selfie_path]||null,extra:p.extra_paths.map(x=>m[x]).filter(Boolean)};
  if(p.role==="admin"){
    const [us,pp]=await Promise.all([SB.from("profiles").select("*").order("created_at",{ascending:false}),SB.from("participations").select("*")]);
    S.users=(us.data||[]).map(mapProfile);
    const nm={};S.users.forEach(u=>nm[u.id]=u.nick);
    S.payments=(pp.data||[]).filter(x=>["aguardando_confirmacao","confirmado","recusado"].includes(x.status)).map(x=>({id:x.id,user:nm[x.user_id]||"?",eventId:x.event_id,status:x.status,sent:x.paid_sent_at?new Date(x.paid_sent_at).getTime():new Date(x.matched_at).getTime()}));
  }else{S.users=[];S.payments=[];}
}
async function uploadPhoto(uid,name,dataUrl){const path=uid+"/"+name;const r=await SB.storage.from("photos").upload(path,dataURLtoBlob(dataUrl),{contentType:"image/jpeg",upsert:true});if(r.error)throw r.error;return path;}

